package org.sleepwell.app;
import org.junit.Test;
import java.util.*;
import java.time.*;
import static org.junit.Assert.*;
public final class TravelCueSessionTest {
 static final class Fixture implements TravelCueSession.Clock,TravelCueSession.Scheduler,TravelCueSession.Output,TravelCueSession.Journal {
  long wall=1792706400000L,elapsed=100000;String zone="UTC";boolean alive=true,ready=true,failOn,failOff,failSave;int opens,closes;TravelCueSession.Events events;final List<Boolean> calls=new ArrayList<>();final List<TravelCueSession.State> states=new ArrayList<>();final TreeMap<Long,List<Runnable>> queue=new TreeMap<>();
  public long wall(){return wall;}public long elapsed(){return elapsed;}public String zone(){return zone;}public void at(long at,Runnable callback){queue.computeIfAbsent(at,k->new ArrayList<>()).add(callback);}public void cancel(){queue.clear();}public void save(TravelCueSession.State state){if(failSave)throw new IllegalStateException("Private failed journal");states.add(state);}
  final TravelCueSession.Handle handle=new TravelCueSession.Handle(){public void set(boolean on){calls.add(on);if(on&&failOn||!on&&failOff)throw new IllegalStateException();}public void close(){closes++;calls.add(false);if(failOff)throw new IllegalStateException();}};
  public TravelCueSession.Request open(TravelCueSession.Events value){opens++;events=value;if(ready)value.ready(handle);return ()->{};}
  TravelCueSession create(long delay,long duration){return new TravelCueSession("d679855a-69a3-4cc9-8a1f-e4906a00ea92",new TravelCuePlan.Window(wall+delay,wall+delay+duration,LocalDate.of(2026,10,22)),this,this,this,this,()->alive);}
  void advance(long millis){long target=elapsed+millis;while(!queue.isEmpty()&&queue.firstKey()<=target){Map.Entry<Long,List<Runnable>> next=queue.pollFirstEntry();long delta=Math.max(0,next.getKey()-elapsed);elapsed+=delta;wall+=delta;for(Runnable r:next.getValue())r.run();}long delta=target-elapsed;elapsed=target;wall+=delta;}
 }
 @Test public void armingFutureWindowNeverConstructsOrTouchesLight(){Fixture f=new Fixture();TravelCueSession s=f.create(60000,60000);s.start();assertEquals(TravelCueSession.Phase.ARMED,s.state().phase);assertEquals(0,f.opens);assertTrue(f.calls.isEmpty());f.advance(59999);assertTrue(f.calls.isEmpty());}
 @Test public void requestedPulseOffAndIntervalUseOriginalAbsoluteWindow(){Fixture f=new Fixture();TravelCueSession s=f.create(0,30000);s.start();assertEquals(List.of(true),f.calls);f.advance(1);assertEquals(1,f.calls.size());f.advance(1);assertEquals(List.of(true,false),f.calls);f.advance(14998);assertEquals(List.of(true,false,true),f.calls);f.advance(15000);assertEquals(TravelCueSession.Phase.FINISHED,s.state().phase);assertEquals(2,s.state().requests);}
 @Test public void explicitStopInvalidatesAllQueuedCallbacks(){Fixture f=new Fixture();TravelCueSession s=f.create(0,60000);s.start();s.stop("User stopped cues");int commands=f.calls.size();f.advance(120000);assertEquals(commands,f.calls.size());assertEquals(TravelCueSession.Phase.STOPPED,s.state().phase);}
 @Test public void lostManualOwnershipStopsWithoutFurtherOn(){Fixture f=new Fixture();TravelCueSession s=f.create(0,60000);s.start();f.advance(2);f.alive=false;f.advance(15000);assertEquals(TravelCueSession.Phase.STOPPED,s.state().phase);assertEquals(1,s.state().requests);}
 @Test public void lateTicksSkipMissedIndicesRatherThanBurst(){Fixture f=new Fixture();TravelCueSession s=f.create(0,60000);s.start();f.advance(2);List<Runnable> next=f.queue.remove(115000L);assertNotNull(next);f.elapsed+=45998;f.wall+=45998;for(Runnable r:next)r.run();assertEquals(1,s.state().requests);assertTrue(s.state().skipped>=1);f.advance(14000);assertEquals(TravelCueSession.Phase.FINISHED,s.state().phase);assertEquals(1,s.state().requests);}
 @Test public void armingRemainingWindowDoesNotExtendTheSelectedDeadline(){Fixture f=new Fixture();TravelCueSession s=f.create(-20000,60000);long end=s.end;s.start();assertEquals(0,s.state().requests);f.advance(40000);assertEquals(end,s.state().end);assertEquals(TravelCueSession.Phase.FINISHED,s.state().phase);assertEquals(2,s.state().requests);}
 @Test public void openThatNeverCompletesHasBoundedError(){Fixture f=new Fixture();f.ready=false;TravelCueSession s=f.create(0,60000);s.start();f.advance(3500);assertEquals(TravelCueSession.Phase.ERROR,s.state().phase);assertTrue(f.calls.isEmpty());}
 @Test public void staleReadyAfterCancellationClosesInsteadOfActivating(){Fixture f=new Fixture();f.ready=false;TravelCueSession s=f.create(0,60000);s.start();s.stop("cancelled");f.events.ready(f.handle);assertFalse(f.calls.contains(true));assertEquals(1,f.closes);}
 @Test public void clockJumpCancelsInsteadOfChangingWindowPrescription(){Fixture f=new Fixture();TravelCueSession s=f.create(60000,60000);s.start();f.wall+=3600000;f.advance(1000);assertEquals(TravelCueSession.Phase.STOPPED,s.state().phase);assertTrue(f.calls.isEmpty());}
 @Test public void deviceZoneChangeRequiresExplicitReview(){Fixture f=new Fixture();TravelCueSession s=f.create(0,60000);s.start();f.advance(2);f.zone="Asia/Riyadh";f.advance(15000);assertEquals(TravelCueSession.Phase.STOPPED,s.state().phase);assertEquals(1,s.state().requests);}
 @Test public void failedOnHasRealErrorAndNoLaterPulse(){Fixture f=new Fixture();f.failOn=true;TravelCueSession s=f.create(0,60000);s.start();assertEquals(TravelCueSession.Phase.ERROR,s.state().phase);f.advance(60000);assertEquals(1,s.state().requests);}
 @Test public void failedOffCannotBecomeSuccessfulCompletion(){Fixture f=new Fixture();f.failOff=true;TravelCueSession s=f.create(0,60000);s.start();f.advance(2);assertEquals(TravelCueSession.Phase.ERROR,s.state().phase);}
 @Test public void failedJournalCannotActivateLight(){Fixture f=new Fixture();f.failSave=true;TravelCueSession s=f.create(0,60000);assertThrows(IllegalStateException.class,s::start);assertFalse(f.calls.contains(true));assertEquals(TravelCueSession.Phase.ERROR,s.state().phase);}
 @Test public void expiredFarFutureAndNonmanualAdmissionAreRejected(){Fixture f=new Fixture();assertThrows(IllegalArgumentException.class,()->f.create(-60000,30000));assertThrows(IllegalArgumentException.class,()->f.create(TravelCueSession.MAX_WAIT+1,60000));f.alive=false;assertThrows(IllegalArgumentException.class,()->f.create(0,60000));assertTrue(f.calls.isEmpty());}
 @Test public void duplicateArmCannotRestartAWindow(){Fixture f=new Fixture();TravelCueSession s=f.create(0,60000);s.start();long end=s.end;assertThrows(IllegalStateException.class,s::start);assertEquals(end,s.end);assertEquals(1,s.state().requests);}
}
